<?php

declare(strict_types=1);

namespace Domain\Memory\Api;

use App\Api\Contracts\Domains\ApiSender;
use App\Support\CallKey;

/**
 * The API of Memory, generated by php artisan journal:api; run it again instead of editing.
 */
final readonly class MemoryApi
{
    public function __construct(private ApiSender $sender) {}

    public function editMemory(
        string $memoryId,
        int $revision,
        string|null $text,
        int|null $weight,
        CallKey $requestKey = new CallKey(),
    ): MemoryNamed {
        return $this->sender->send(EditMemoryPayload::from([
            'memoryId' => $memoryId,
            'revision' => $revision,
            'text' => $text,
            'weight' => $weight,
            'requestKey' => $requestKey,
        ]));
    }

    public function listMemories(
        int $page = 1,
    ): MemoryPage {
        return $this->sender->send(ListMemoriesPayload::from(['page' => $page]));
    }

    public function removeMemory(
        string $memoryId,
        CallKey $requestKey = new CallKey(),
    ): MemoryNamed {
        return $this->sender->send(RemoveMemoryPayload::from(['memoryId' => $memoryId, 'requestKey' => $requestKey]));
    }

    public function saveMemory(
        string $text,
        int $weight,
        CallKey $requestKey = new CallKey(),
    ): MemoryNamed {
        return $this->sender->send(SaveMemoryPayload::from([
            'text' => $text,
            'weight' => $weight,
            'requestKey' => $requestKey,
        ]));
    }
}
